const $=id=>document.getElementById(String(id).replace(/^#/,''));
const debugLog=[];
function logDebug(message, level='INFO'){ const stamp=new Date().toLocaleTimeString(); const line=`[${stamp}] ${level}: ${message}`; debugLog.push(line); if(debugLog.length>30) debugLog.shift(); console.log(line); const el=document.getElementById('debugLog'); if(el) el.textContent=debugLog.join('\n'); }
window.addEventListener('error', e=>{ logDebug(`${e.message} @ ${e.filename||'inline'}:${e.lineno||'?'}:${e.colno||'?'}`,'ERROR'); });
window.addEventListener('unhandledrejection', e=>{ logDebug(`Unhandled promise rejection: ${e.reason?.message || e.reason || 'unknown'}`,'ERROR'); });
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const mean=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:0;

function operatingMode(I){
  if(I<-2)return{name:'CHARGING',color:'#0ea5e9',reason:`Charge current ${Math.abs(I).toFixed(1)} A`};
  if(I>2)return{name:'DISCHARGING',color:'#f59e0b',reason:`Load current ${I.toFixed(1)} A`};
  return{name:'IDLE / REST',color:'#64748a',reason:'Pack current is near zero'};
}
function spatialWeight(cell,sensor){
  // 1-D thermal propagation along the cell string. Sparse sensors are at C1, C2 and C12.
  // This gives each hidden candidate a distinct three-sensor thermal signature.
  return Math.exp(-Math.abs(cell-sensor)/3.0);
}
function resetEstimator(){
  estimatorState={scores:Object.fromEntries(candidateCells.map(i=>[i,0])),fits:{},history:[],detected:null,confidence:0,deltaR:0};
}
function chooseHiddenFault(){
  actualFaultCell=candidateCells[Math.floor(Math.random()*candidateCells.length)];
  logDebug(`Hidden plant fault selected: C${actualFaultCell+1} (DT is not given this value)`);
}
function healthyModel(r){
  const I=Math.max(0,Number(r.pack_current_A));
  const t=Number(r.time_s);
  const ambient=Number(r.ambient_C);
  // All cells start at exactly 36.5 C. A first-order thermal state then follows load and ambient.
  const target=ambient + 7.5 + 0.078*I;
  const tau=75;
  const rise=(target-36.5)*(1-Math.exp(-t/tau));
  const coolingDrift= t>360 ? -0.018*(t-360) : 0;
  const baseTemp=36.5+rise+coolingDrift;
  // Spatial thermal field: all cells start exactly at 36.5 C, then a realistic
  // pack-level gradient develops as heat builds up. The gradient is independent
  // of the hidden fault, so the DT has a healthy spatial baseline to compare against.
  const spatialRamp=(1-Math.exp(-t/95));
  // Healthy pack thermal field: a genuine cell-to-cell gradient plus small
  // local differences. The field is generated without knowing the hidden fault.
  // C1 is near the coolant inlet, C12 is near the warmer outlet.
  const positions=[0.00,0.08,0.17,0.25,0.33,0.42,0.50,0.58,0.67,0.75,0.83,1.00];
  const spatialGradient=positions.map(x=>(x-0.5)*1.8*spatialRamp);
  const localPattern=[-0.12,0.06,-0.08,0.10,-0.05,0.07,-0.08,0.09,-0.06,0.07,-0.04,0.08].map(v=>v*spatialRamp);
  // Local heat-load weighting makes the middle cells slightly warmer at high load.
  const loadShape=[0.90,0.96,1.00,1.04,1.08,1.12,1.15,1.13,1.08,1.03,0.98,0.94];
  const loadRise=loadShape.map(q=>0.32*(I/150)*q*spatialRamp);
  const temps=Array.from({length:12},(_,i)=>baseTemp+spatialGradient[i]+localPattern[i]+loadRise[i]);
  measuredCells.forEach((c,j)=>temps[c]=baseTemp+spatialGradient[c]+localPattern[c]);

  const soc=Number(r.soc_pct);
  const ocv=3.15+1.0*clamp(soc/100,0,1)+0.0015*(mean(temps)-25);
  const vPred=12*(ocv-I*NOMINAL_R_MOHM/1000);
  const qHeat=12*(I*I*NOMINAL_R_MOHM/1000);
  const flow=Math.max(0.5,Number(r.coolant_flow_Lmin));
  const coolantPred=Number(r.coolant_in_C)+qHeat/(flow*0.07*4180);
  return {temps,vPred,coolantPred,ocv};
}
function plantRow(base){
  const r={...base};
  const I=Math.max(0,Number(base.pack_current_A));
  const t=Number(base.time_s);
  const healthy=healthyModel(base);
  // Fault severity starts at zero at t=0 and ramps gradually. Ground truth is hidden from DT.
  const progress=clamp((t-15)/180,0,1);
  const faultFactor=1+1.2*progress; // nominal -> 2.2x R
  const deltaR=NOMINAL_R_MOHM*(faultFactor-1);
  const extraQ=I*I*deltaR/1000;

  // Pack electrical measurement contains the aggregate signature of the hidden degraded cell.
  r.pack_voltage_V=healthy.vPred-I*deltaR/1000 + 0.006*Math.sin(t*0.37);

  // Sparse measured temperatures carry a small spatial footprint from the hidden fault.
  measuredCells.forEach((sensor,j)=>{
    const w=spatialWeight(actualFaultCell,sensor);
    const rise=extraQ*0.085*w*(1-Math.exp(-t/75));
    r[['T1_C','T2_C','T3_C'][j]]=healthy.temps[sensor]+rise+0.04*Math.sin(t*0.41+j);
  });
  // Exact common initial condition.
  if(t===0){r.T1_C=r.T2_C=r.T3_C=36.5;}

  const flow=Math.max(0.5,Number(base.coolant_flow_Lmin));
  const healthyDelta=healthy.coolantPred-Number(base.coolant_in_C);
  r.coolant_out_C=Number(base.coolant_in_C)+healthyDelta+extraQ/(flow*0.07*4180)*0.22*(1-Math.exp(-t/100));
  if(t===0) r.coolant_out_C=Number(base.coolant_in_C)+0.05;
  return r;
}
function cellStates(r,healthy,estimate){
  const states=[];
  const detected=estimate.detected;
  // Sparse reconstruction: only the currently selected candidate is allowed to
  // carry a significant parameter deviation. Other cells remain near nominal.
  const detectedR = detected!==null
    ? clamp(NOMINAL_R_MOHM + (estimate.deltaR||0), NOMINAL_R_MOHM, NOMINAL_R_MOHM+14)
    : NOMINAL_R_MOHM;
  for(let i=0;i<12;i++){
    const R=i===detected?detectedR:NOMINAL_R_MOHM;
    const soh=100-clamp((R-NOMINAL_R_MOHM)*2.5,0,30);
    const temp=healthy.temps[i] + (i===detected?clamp((R-NOMINAL_R_MOHM)*0.45,0,8):0);
    states.push({temp,soh,R});
  }
  measuredCells.forEach((c,j)=>states[c].temp=Number(r[['T1_C','T2_C','T3_C'][j]]));
  const initialSoc=Number(data[0]?.soc_pct ?? r.soc_pct);
  const used=Math.max(0,(initialSoc-Number(r.soc_pct))/100);
  const soc=states.map((s,i)=>clamp(Number(r.soc_pct)+(i===detected?-used*2.5:0),0,100));
  return {states,soc,packSOH:Math.min(...states.map(s=>s.soh))};
}
function updateEstimator(r,healthy){
  const I=Math.max(1,Number(r.pack_current_A));
  // Positive residual means the measured pack voltage is lower than the healthy model.
  const vResidual=healthy.vPred-Number(r.pack_voltage_V);
  const qResidual=(Number(r.coolant_out_C)-Number(r.coolant_in_C))-(healthy.coolantPred-Number(r.coolant_in_C));
  const thermalResidual=measuredCells.map((c,j)=>Number(r[['T1_C','T2_C','T3_C'][j]])-healthy.temps[c]);
  const y=thermalResidual.map(x=>Math.max(0,x));
  const yNorm=Math.sqrt(y.reduce((a,b)=>a+b*b,0));

  // Aggregate electrical evidence: pack voltage can reveal that extra resistance exists,
  // but cannot localize it by itself.
  const deltaREst=clamp(vResidual*1000/I,0,14);
  const thermalAnomaly=clamp(yNorm/0.65,0,3);

  candidateCells.forEach(c=>{
    const w=measuredCells.map(s=>spatialWeight(c,s));
    const ww=w.reduce((a,b)=>a+b*b,0);
    const wy=w.reduce((a,b,j)=>a+b*y[j],0);
    const amp=Math.max(0,wy/Math.max(ww,1e-9));
    const pred=w.map(x=>x*amp);
    const err=Math.sqrt(pred.reduce((a,p,j)=>a+(p-y[j])**2,0)/y.length);
    const denom=yNorm+0.04;
    const fit=clamp(1-err/denom,0,1);
    const correlation=yNorm>0.01?clamp(wy/(Math.sqrt(ww)*yNorm),0,1):0;
    // Sparse evidence: electrical anomaly is global, spatial thermal pattern does the localization.
    const localEvidence=0.60*fit+0.35*correlation+0.05*clamp(qResidual/0.15,0,1);
    const score=clamp((deltaREst*0.16 + thermalAnomaly*1.05)*localEvidence,0,10);
    estimatorState.scores[c]=0.90*estimatorState.scores[c]+0.10*score;
    estimatorState.fits[c]={fit,correlation,amp};
  });

  const ranked=candidateCells.slice().sort((a,b)=>estimatorState.scores[b]-estimatorState.scores[a]);
  const top=ranked[0], second=ranked[1]??top;
  const gap=estimatorState.scores[top]-estimatorState.scores[second];
  const evidence=estimatorState.scores[top];
  if(Number(r.time_s)%10===0){ logDebug(`Fault ranking: C${top+1}=${evidence.toFixed(2)}, C${second+1}=${estimatorState.scores[second].toFixed(2)}, gap=${gap.toFixed(3)}, dR=${deltaREst.toFixed(2)}mΩ`); }
  // Require persistent evidence and a meaningful separation from the runner-up.
  if(Number(r.time_s)>=25 && deltaREst>0.15 && evidence>0.22 && gap>0.035){
    estimatorState.detected=top;
    estimatorState.deltaR=clamp(deltaREst,0,14);
    estimatorState.confidence=clamp(55+gap*150+evidence*5,0,98);
  } else {
    estimatorState.detected=null;
    estimatorState.deltaR=0;
    estimatorState.confidence=0;
  }
  estimatorState.history.push({t:Number(r.time_s),vResidual,thermalResidual,qResidual,top,score:evidence,deltaREst,gap});
  if(estimatorState.history.length>240)estimatorState.history.shift();
  return {vResidual,qResidual,thermalResidual,deltaREst};
}
function svgLine(points,color,width=2,dash=''){
  return `<polyline fill="none" stroke="${color}" stroke-width="${width}" ${dash?`stroke-dasharray="${dash}"`:''} points="${points.map(p=>p.join(',')).join(' ')}"/>`;
}
function setMode(r){
  const m=operatingMode(r.pack_current_A);
  $('operatingMode').textContent=m.name;$('modeReason').textContent=m.reason;
  $('modeDot').style.background=m.color;$('modeDot').style.boxShadow=`0 0 0 5px ${m.color}22`;
  $('modeValue').textContent=m.name;$('modeMetric').style.borderTopColor=m.color;
}
function drawTimeChart(elId,series,min,max,label){
  const arr=data.slice(Math.max(0,idx-180),idx+1);if(!arr.length)return;
  const W=760,H=250,p=32,x=j=>p+j*(W-2*p)/Math.max(1,arr.length-1),y=v=>H-p-(v-min)/(max-min)*(H-2*p);
  let svg=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="100%"><line x1="${p}" y1="${H-p}" x2="${W-p}" y2="${H-p}" stroke="#cbd5e1"/><line x1="${p}" y1="${p}" x2="${p}" y2="${H-p}" stroke="#cbd5e1"/><text x="${p}" y="15" font-size="11" fill="#64748a">${label}</text>`;
  series.forEach(s=>{const pts=arr.map((r,j)=>[x(j),y(s.get(r))]);svg+=svgLine(pts,s.color,s.width||2,s.dash||''); if(pts.length===1) svg+=`<circle cx="${pts[0][0]}" cy="${pts[0][1]}" r="4" fill="${s.color}"/>`;});
  svg+='</svg>';$(`#${elId}`).innerHTML=svg;
}
function drawAllTempChart(models){
  const arr=data.slice(Math.max(0,idx-180),idx+1);if(!arr.length)return;
  const W=760,H=270,p=34,min=34,max=56,x=j=>p+j*(W-2*p)/Math.max(1,arr.length-1),y=v=>H-p-(v-min)/(max-min)*(H-2*p);
  let svg=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="100%"><line x1="${p}" y1="${H-p}" x2="${W-p}" y2="${H-p}" stroke="#cbd5e1"/><line x1="${p}" y1="${p}" x2="${p}" y2="${H-p}" stroke="#cbd5e1"/><text x="${p}" y="15" font-size="11" fill="#64748a">Temperature (°C)</text>`;
  for(let i=0;i<12;i++){
    const pts=arr.map((rr,j)=>{
      const hm=healthyModel(rr); const est=cellStates(rr,hm,estimatorState); return [x(j),y(est.states[i].temp)];
    });
    const col=i===estimatorState.detected?'#ef4444':(measuredCells.includes(i)?'#16a66a':'#2563eb');
    svg+=svgLine(pts,col,i===estimatorState.detected?4:1.5,i===estimatorState.detected?'':'4 4');
  }
  svg+='</svg>';$('allTempChart').innerHTML=svg;
}
function drawBars(elId,vals,label,unit,highlight){
  const W=760,H=230,p=36,min=Math.min(...vals)-1,max=Math.max(...vals)+1,bw=(W-2*p)/12*0.62;
  let svg=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="100%"><line x1="${p}" y1="${H-p}" x2="${W-p}" y2="${H-p}" stroke="#cbd5e1"/><text x="${p}" y="15" font-size="11" fill="#64748a">${label}</text>`;
  vals.forEach((v,i)=>{const xx=p+i*(W-2*p)/12+(W-2*p)/12*.19,yy=H-p-(v-min)/(max-min)*(H-2*p),hh=H-p-yy,col=i===highlight?'#ef4444':(measuredCells.includes(i)?'#16a66a':'#2563eb');svg+=`<rect x="${xx}" y="${yy}" width="${bw}" height="${hh}" rx="4" fill="${col}"/><text x="${xx+bw/2}" y="${H-p+15}" text-anchor="middle" font-size="9" fill="#64748a">C${i+1}</text><text x="${xx+bw/2}" y="${yy-5}" text-anchor="middle" font-size="9" font-weight="700" fill="${col}">${v.toFixed(1)}${unit}</text>`;});
  svg+='</svg>';$(`#${elId}`).innerHTML=svg;
}
function drawCellSocChart(soc,highlight){drawBars('cellSocChart',soc,'Estimated cell SOC','%',highlight);}
function drawHealthChart(states,highlight){drawBars('healthChart',states.map(s=>s.soh),'Estimated SOH','%',highlight);}
function drawResistanceChart(states,highlight){drawBars('resistanceChart',states.map(s=>s.R),'Estimated resistance',' mΩ',highlight);}
function drawSocHistory(inferred){
  const arr=data.slice(Math.max(0,idx-180),idx+1);if(!arr.length)return;
  const W=760,H=230,p=32,min=50,max=82,x=j=>p+j*(W-2*p)/Math.max(1,arr.length-1),y=v=>H-p-(v-min)/(max-min)*(H-2*p);
  const pack=arr.map((rr,j)=>[x(j),y(Number(rr.soc_pct))]);
  const d=estimatorState.detected;
  const cell=arr.map((rr,j)=>{const hm=healthyModel(rr);const es=cellStates(rr,hm,estimatorState);return [x(j),y(es.soc[d??candidateCells[0]])];});
  $('socChart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" width="100%" height="100%"><line x1="${p}" y1="${H-p}" x2="${W-p}" y2="${H-p}" stroke="#cbd5e1"/><line x1="${p}" y1="${p}" x2="${p}" y2="${H-p}" stroke="#cbd5e1"/><text x="${p}" y="15" font-size="11" fill="#64748a">SOC (%)</text>${svgLine(pack,'#16a66a',3)}${svgLine(cell,'#2563eb',3,'8 6')}</svg>`;
}
function safeStage(name, fn){
  logDebug(`STAGE ${name} begin`);
  try{ const out=fn(); logDebug(`STAGE ${name} OK`); return out; }
  catch(err){ logDebug(`STAGE ${name} FAILED: ${err?.message || err}`,'ERROR'); console.error(`Stage ${name} failed`,err); return null; }
}
function render(){
  if(!data.length){ logDebug('Render skipped: no data','WARN'); return; }
  logDebug(`RENDER start idx=${idx}, t=${data[idx]?.time_s ?? '?'}s, running=${running}`);
  try{
    const r=plantRow(data[idx]);
    logDebug(`Plant row OK: I=${Number(r.pack_current_A).toFixed(1)}A`);
    const healthy=healthyModel(r);
    logDebug(`Healthy model OK: Tbase=${healthy.temps[0].toFixed(2)}C, Vpred=${healthy.vPred.toFixed(3)}V`);
    const residuals=updateEstimator(r,healthy);
    logDebug(`Estimator OK: vRes=${residuals.vResidual.toFixed(4)}V, detected=${estimatorState.detected===null?'none':'C'+(estimatorState.detected+1)}`);
    const inferred=cellStates(r,healthy,estimatorState);
    logDebug(`State reconstruction OK: hottest=${Math.max(...inferred.states.map(s=>s.temp)).toFixed(2)}C`);
    safeStage('mode',()=>setMode(r));
    safeStage('sensors',()=>{$('sensors').innerHTML=[['Pack current',`${r.pack_current_A.toFixed(1)} A`],['Pack voltage',`${r.pack_voltage_V.toFixed(2)} V`],['Pack SOC',`${r.soc_pct.toFixed(1)} %`],['T1 • C1',`${r.T1_C.toFixed(1)} °C`],['T2 • C2',`${r.T2_C.toFixed(1)} °C`],['T3 • C12',`${r.T3_C.toFixed(1)} °C`],['Coolant flow',`${r.coolant_flow_Lmin.toFixed(2)} L/min`]].map(x=>`<div class="sensorrow"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');});
    const hot=inferred.states.reduce((a,s,i)=>s.temp>a.t?{i,t:s.temp}:{i:a.i,t:a.t},{i:0,t:-1});
    safeStage('kpis',()=>{
      $('hot').textContent=`C${hot.i+1} • ${hot.t.toFixed(1)} °C`; $('soh').textContent=`${inferred.packSOH.toFixed(1)} %`;
      const d=estimatorState.detected;
      $('detectedSohLabel').textContent=d!==null?`C${d+1} SOH`:'Detected Cell SOH'; $('detectedSocLabel').textContent=d!==null?`C${d+1} SOC`:'Detected Cell SOC';
      $('detectedSoh').textContent=d!==null?`${inferred.states[d].soh.toFixed(1)} %`:'—'; $('detectedSoc').textContent=d!==null?`${inferred.soc[d].toFixed(1)} %`:'—'; $('res').textContent=d!==null?`${inferred.states[d].R.toFixed(1)} mΩ`:'—'; $('risk').textContent=d!==null?(inferred.states[d].temp>47?'HIGH':'WATCH'):'NORMAL';
      $('current').textContent=`${r.pack_current_A.toFixed(1)} A`; $('voltage').textContent=`${r.pack_voltage_V.toFixed(2)} V`; $('soc').textContent=`${r.soc_pct.toFixed(1)} %`; $('tout').textContent=`${r.coolant_out_C.toFixed(1)} °C`;
      const cr=Math.max(0,r.pack_current_A)/NOMINAL_AH; $('rateValue').textContent=`${cr.toFixed(2)} C`; $('drate').textContent=`${cr.toFixed(2)} C`; $('crate').textContent=`${cr.toFixed(2)} C`; $('cycle').textContent=`t = ${r.time_s}s / ${TOTAL_STEPS-1}s`;
    });
    safeStage('battery cards',()=>{$('battery').innerHTML=inferred.states.map((st,i)=>{const meas=measuredCells.includes(i), detected=estimatorState.detected===i; const c=detected?'fault':(meas?'measured':''); return `<div class="cell ${c}"><div class="tag">${meas?'MEASURED':'DT ESTIMATE'}${detected?'<span class="fault-badge">DT FAULT</span>':''}</div><div class="n">CELL ${i+1}</div><div class="t">${st.temp.toFixed(1)}°C</div><div class="h">SOC ${inferred.soc[i].toFixed(1)}%</div><div class="soc">SOH ${st.soh.toFixed(1)}%</div><div class="healthbar"><i style="width:${st.soh}%;background:${detected?'#ef4444':meas?'#16a66a':'#2563eb'}"></i></div><div class="r">R ${st.R.toFixed(1)} mΩ</div></div>`;}).join('');});
    safeStage('temperature chart',()=>drawAllTempChart(inferred));
    safeStage('history chart',()=>drawTimeChart('tempChart',[{color:'#16a66a',width:3,get:r=>r.T2_C},{color:'#2563eb',width:3,dash:'8 6',get:r=>{const hm=healthyModel(r);return cellStates(r,hm,estimatorState).states[estimatorState.detected??5].temp}}],34,56,'Temperature (°C)'));
    safeStage('SOH chart',()=>drawHealthChart(inferred.states,estimatorState.detected));
    safeStage('R chart',()=>drawResistanceChart(inferred.states,estimatorState.detected));
    safeStage('SOC chart',()=>drawCellSocChart(inferred.soc,estimatorState.detected));
    safeStage('SOC history',()=>drawSocHistory(inferred));
    safeStage('explanation',()=>{
      const d=estimatorState.detected; const status=d===null?'FAULT UNKNOWN — observing residuals':'ANOMALY DETECTED — likely Cell '+(d+1);
      $('explain').innerHTML=`<b>${status}</b><br>DT uses only pack voltage/current/SOC, three sparse temperature sensors and coolant measurements. The plant fault location is hidden from the estimator. Voltage residual = <b>${residuals.vResidual.toFixed(3)} V</b>; thermal residual magnitude = <b>${mean(residuals.thermalResidual.map(Math.abs)).toFixed(3)} °C</b>. ${d!==null?`Model-based candidate confidence: <b>${estimatorState.confidence.toFixed(0)}%</b>.`:'The estimator is accumulating evidence.'}`;
      $('healthSummary').innerHTML=`<div class="note"><b>Blind-fault experiment:</b> one hidden cell is degraded internally. The DT is not told which cell it is.</div>`;
      const rankedEvidence=candidateCells.slice().sort((a,b)=>estimatorState.scores[b]-estimatorState.scores[a]); $('healthSummary').innerHTML+=`<div class="note" style="margin-top:8px"><b>Fault evidence:</b> ${rankedEvidence.slice(0,3).map(c=>`C${c+1}: ${estimatorState.scores[c].toFixed(2)}`).join(' • ')}</div>`;
      $('live').textContent=running?`● LIVE — t = ${r.time_s}s / ${TOTAL_STEPS-1}s`:`Ⅱ PAUSED — t = ${r.time_s}s`;
    });
    logDebug(`RENDER complete idx=${idx}`);
  }catch(err){
    logDebug(`RENDER FAILED: ${err?.message || err}`,'ERROR'); console.error('RENDER FAILED',err);
    const live=$('live'); if(live) live.textContent='⚠ RENDER ERROR — see Debug Log';
  }
}

function scheduleNext(){
  clearTimeout(timer);
  if(running){ logDebug(`Scheduling next step in ${SIM_MS} ms`); timer=setTimeout(step,SIM_MS); }
}
function step(){
  logDebug(`STEP entered: running=${running}, idx=${idx}, data=${data.length}`);
  if(!running||!data.length){ logDebug('STEP skipped','WARN'); return; }
  try{
    if(idx < data.length-1) idx++; else { running=false; logDebug('Reached final sample'); return; }
    render();
    if(idx >= data.length-1){ running=false; $('live').textContent=`✓ COMPLETE — t = ${data[idx].time_s}s / ${TOTAL_STEPS-1}s`; logDebug('Simulation complete'); return; }
    scheduleNext();
  }catch(err){
    running=false; clearTimeout(timer); logDebug(`STEP FAILED: ${err?.message || err}`,'ERROR'); console.error(err); const live=$('live'); if(live) live.textContent='⚠ STEP ERROR — see Debug Log';
  }
}
function startTimer(){
  clearTimeout(timer); logDebug(`startTimer called; running=${running}; idx=${idx}`); if(running) scheduleNext();
}
$('pause').addEventListener('click',()=>{
  if(running){
    running=false;
    clearTimeout(timer);
    $('live').textContent=`Ⅱ PAUSED — t = ${data[idx]?.time_s ?? 0}s`;
  }else{
    running=true;
    $('live').textContent='● LIVE — BLIND FAULT ESTIMATION';
    scheduleNext();
  }
});
$('reset').addEventListener('click',()=>{
  clearTimeout(timer);
  idx=0;
  chooseHiddenFault();
  resetEstimator();
  running=true;
  render();
  startTimer();
});
$('file').addEventListener('change',async e=>{
  const f=e.target.files[0]; if(!f)return;
  try{
    const text=await f.text();
    const rows=f.name.toLowerCase().endsWith('.json')?JSON.parse(text):text.trim().split(/\r?\n/).slice(1).map(line=>{const v=line.split(',');return {time_s:Number(v[0]),pack_current_A:Number(v[1]),pack_voltage_V:Number(v[2]),soc_pct:Number(v[3]),ambient_C:Number(v[4]),coolant_in_C:Number(v[5]),coolant_out_C:Number(v[6]),coolant_flow_Lmin:Number(v[7]),T1_C:Number(v[8]),T2_C:Number(v[9]),T3_C:Number(v[10])};});
    data=rows.filter(x=>Number.isFinite(x.pack_current_A)); idx=0; chooseHiddenFault(); resetEstimator(); running=true; render(); startTimer();
  }catch(err){alert('Could not read this sensor file.');}
});

// Start automatically. Fault location is randomized internally and never passed to the estimator.
try{
  logDebug('BOOT: creating simulation data');
  data=baseData.map(x=>({...x}));
  chooseHiddenFault();
  resetEstimator();
  data[0].T1_C=data[0].T2_C=data[0].T3_C=36.5;
  running=true;
  logDebug('BOOT: initial render');
  render();
  logDebug('BOOT: starting timer');
  startTimer();
}catch(err){
  running=false; logDebug(`BOOT FAILED: ${err?.message || err}`,'ERROR'); console.error(err);
}
